+        this.type = Objects.requireNonNull(type);
+        this.code = code;
+        this.param = param;
+    }
+
+    public UnifiedChatCompletionException(
+        Throwable cause,
+        RestStatus status,
+        String message,
+        String type,
+        @Nullable String code,
+        @Nullable String param
+    ) {
+        super(message, cause, status);
