+    public Iterator<? extends ToXContent> toXContentChunkedV8(Params params) {
+        return ChunkedToXContent.super.toXContentChunkedV8(params);
+    }
+
+    @Override
+    public boolean isFragment() {
+        return super.isFragment();
+    }
+}

